(function(){
const KANA = {
あ:'a',い:'i',う:'u',え:'e',お:'o',か:'ka',き:'ki',く:'ku',け:'ke',こ:'ko',さ:'sa',し:'shi',す:'su',せ:'se',そ:'so',た:'ta',ち:'chi',つ:'tsu',て:'te',と:'to',な:'na',に:'ni',ぬ:'nu',ね:'ne',の:'no',は:'ha',ひ:'hi',ふ:'fu',へ:'he',ほ:'ho',ま:'ma',み:'mi',む:'mu',め:'me',も:'mo',や:'ya',ゆ:'yu',よ:'yo',ら:'ra',り:'ri',る:'ru',れ:'re',ろ:'ro',わ:'wa',を:'wo',ん:'n',
が:'ga',ぎ:'gi',ぐ:'gu',げ:'ge',ご:'go',ざ:'za',じ:'ji',ず:'zu',ぜ:'ze',ぞ:'zo',だ:'da',ぢ:'ji',づ:'zu',で:'de',ど:'do',ば:'ba',び:'bi',ぶ:'bu',べ:'be',ぼ:'bo',ぱ:'pa',ぴ:'pi',ぷ:'pu',ぺ:'pe',ぽ:'po',
ア:'a',イ:'i',ウ:'u',エ:'e',オ:'o',カ:'ka',キ:'ki',ク:'ku',ケ:'ke',コ:'ko',サ:'sa',シ:'shi',ス:'su',セ:'se',ソ:'so',タ:'ta',チ:'chi',ツ:'tsu',テ:'te',ト:'to',ナ:'na',ニ:'ni',ヌ:'nu',ネ:'ne',ノ:'no',ハ:'ha',ヒ:'hi',フ:'fu',ヘ:'he',ホ:'ho',マ:'ma',ミ:'mi',ム:'mu',メ:'me',モ:'mo',ヤ:'ya',ユ:'yu',ヨ:'yo',ラ:'ra',リ:'ri',ル:'ru',レ:'re',ロ:'ro',ワ:'wa',ヲ:'wo',ン:'n',
ガ:'ga',ギ:'gi',グ:'gu',ゲ:'ge',ゴ:'go',ザ:'za',ジ:'ji',ズ:'zu',ゼ:'ze',ゾ:'zo',ダ:'da',ヂ:'ji',ヅ:'zu',デ:'de',ド:'do',バ:'ba',ビ:'bi',ブ:'bu',ベ:'be',ボ:'bo',パ:'pa',ピ:'pi',プ:'pu',ペ:'pe',ポ:'po'
};
const PARTICLES = {
は:'topik/subject marker',が:'penanda subjek atau fokus',を:'penanda objek langsung',に:'waktu, tujuan, lokasi',へ:'arah/tujuan',で:'tempat aksi atau alat',と:'dengan/dan/kutipan',も:'juga',の:'kepunyaan/penjelas',から:'dari/karena',まで:'sampai',より:'daripada/dari',ね:'ya kan/konfirmasi',よ:'penegasan'
};
const COMMON = [
['私','わたし','saya'],['あなた','あなた','kamu'],['彼','かれ','dia laki-laki'],['彼女','かのじょ','dia perempuan'],['日本','にほん','Jepang'],['日本語','にほんご','bahasa Jepang'],['勉強','べんきょう','belajar'],['学校','がっこう','sekolah'],['先生','せんせい','guru'],['学生','がくせい','pelajar'],['今日','きょう','hari ini'],['明日','あした','besok'],['昨日','きのう','kemarin'],['食べる','たべる','makan'],['飲む','のむ','minum'],['行く','いく','pergi'],['来る','くる','datang'],['見る','みる','melihat'],['読む','よむ','membaca'],['書く','かく','menulis'],['話す','はなす','berbicara'],['聞く','きく','mendengar/bertanya'],['大きい','おおきい','besar'],['小さい','ちいさい','kecil'],['新しい','あたらしい','baru'],['古い','ふるい','lama'],['良い','いい','baik'],['悪い','わるい','buruk']
];
const safeJson = (key, fallback) => {
try { return JSON.parse(localStorage.getItem(key) || JSON.stringify(fallback)); }
catch (error) {
localStorage.removeItem(key);
return fallback;
}
};
let vocabPromise;
let entries = [];
let byExpression = new Map();
let history = safeJson('nihongoTranslatorHistory', []);
let apiConfig = safeJson('nihongoTranslatorApi', { endpoint: '', model: '' });
const rootPrefix = (() => {
const path = location.pathname;
if (path.includes('/Materi/') || path.includes('/Dashboard/') || path.includes('/QUIZ/') || path.includes('/AI-Tutor-Page/') || path.includes('/AI-Tutor-Page/') || path.includes('/Landing-Page/') || path.includes('/Landing-Page/')) return '../';
return '';
})();
function esc(value){return String(value || '').replace(/[&<>"']/g, ch => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[ch]));}
function parseCsv(text){
const rows=[]; let row=[], cell='', quote=false;
for(let i=0;i<text.length;i++){
const ch=text[i], next=text[i+1];
if(ch==='"'&&quote&&next==='"'){cell+='"';i++;continue}
if(ch==='"'){quote=!quote;continue}
if(ch===','&&!quote){row.push(cell);cell='';continue}
if((ch==='\n'||ch==='\r')&&!quote){if(ch==='\r'&&next==='\n')i++;row.push(cell);if(row.some(Boolean))rows.push(row);row=[];cell='';continue}
cell+=ch;
}
if(cell||row.length){row.push(cell);rows.push(row)}
return rows;
}
function levelFromTags(tags){for(const n of [5,4,3,2,1]) if(String(tags).includes(`JLPT_N${n}`)||String(tags).includes(`JLPT_${n}`)) return `N${n}`; return 'N1';}
async function loadVocab(){
if (vocabPromise) return vocabPromise;
vocabPromise = fetch(`${rootPrefix}assets/vocab-all.csv`).then(r => r.text()).then(text => {
const parsed = parseCsv(text).slice(1).map((r,i)=>({expression:r[0],reading:r[1],meaning:r[2],level:levelFromTags(r[3] || ''),id:i})).filter(x=>x.expression&&x.meaning);
entries = [...COMMON.map((x,i)=>({expression:x[0],reading:x[1],meaning:x[2],level:'Core',id:`core-${i}`})), ...parsed];
byExpression = new Map();
entries.forEach(item => {
if (!byExpression.has(item.expression)) byExpression.set(item.expression, item);
});
return entries;
}).catch(() => {
entries = COMMON.map((x,i)=>({expression:x[0],reading:x[1],meaning:x[2],level:'Core',id:`core-${i}`}));
byExpression = new Map(entries.map(item => [item.expression,item]));
return entries;
});
return vocabPromise;
}
function hasJapanese(text){return /[\u3040-\u30ff\u3400-\u9fff]/.test(text);}
function romanize(kana){
const small = {ゃ:'ya',ゅ:'yu',ょ:'yo',ャ:'ya',ュ:'yu',ョ:'yo'};
let out = '';
for(let i=0;i<String(kana).length;i++){
const ch = kana[i], next = kana[i+1];
if ((ch === 'っ' || ch === 'ッ') && next) {
const n = KANA[next] || '';
out += n ? n[0] : '';
continue;
}
if (small[next] && KANA[ch]) {
const base = KANA[ch].replace(/i$/,'');
out += base + small[next];
i++;
continue;
}
if (ch === 'ー') continue;
out += KANA[ch] || ch;
if (KANA[ch] && i < String(kana).length - 1) out += ' ';
}
return out.replace(/\s+/g,' ').trim();
}
function tokenizeJapanese(text){
const clean = String(text).replace(/\s+/g,'');
const tokens = [];
let i = 0;
while(i < clean.length){
let found = null;
const max = Math.min(12, clean.length - i);
for(let len=max; len>0; len--){
const part = clean.slice(i, i + len);
if (byExpression.has(part)) { found = byExpression.get(part); break; }
}
if (found) {
tokens.push(found);
i += found.expression.length;
continue;
}
const two = clean.slice(i, i + 2);
if (PARTICLES[two]) {
tokens.push({expression:two,reading:two,meaning:PARTICLES[two],level:'Particle'});
i += 2;
continue;
}
const one = clean[i];
if (PARTICLES[one]) tokens.push({expression:one,reading:one,meaning:PARTICLES[one],level:'Particle'});
else if (/[。、！？,.!?]/.test(one)) tokens.push({expression:one,reading:'',meaning:'tanda baca',level:'Punctuation'});
else tokens.push({expression:one,reading:one,meaning:KANA[one] ? romanize(one) : 'belum ada di kamus lokal',level:KANA[one] ? 'Kana' : 'Unknown'});
i++;
}
return tokens;
}
function translateJapanese(text){
const exact = byExpression.get(text.trim());
if (exact) return {output:`${exact.meaning}\nReading: ${exact.reading}\nLevel: ${exact.level}`, tokens:[exact], source:'Exact dictionary match'};
const tokens = tokenizeJapanese(text);
const meaningful = tokens.filter(t => !['Punctuation'].includes(t.level));
const output = meaningful.map(t => t.meaning).join(' / ');
const reading = meaningful.map(t => t.reading).filter(Boolean).join(' ');
return {output:`${output || 'Belum ditemukan.'}${reading ? `\nReading: ${reading}` : ''}${reading ? `\nRomaji: ${romanize(reading)}` : ''}`, tokens, source:'Local vocabulary + particle parser'};
}
function translateSearch(text){
const terms = text.toLowerCase().split(/\s+/).filter(Boolean);
const results = entries.filter(item => {
const hay = `${item.expression} ${item.reading} ${item.meaning}`.toLowerCase();
return terms.every(term => hay.includes(term));
}).slice(0, 24);
const output = results.length
? results.slice(0, 8).map(item => `${item.expression}（${item.reading}）= ${item.meaning} [${item.level}]`).join('\n')
: 'Belum ditemukan di kamus lokal. Coba kata kunci lain, atau aktifkan mode API.';
return {output, tokens:results, source:'Reverse dictionary search'};
}
let nihongoAiLoadPromise;
function ensureNihongoAi(){
if (window.NihongoAI) return Promise.resolve(window.NihongoAI);
if (nihongoAiLoadPromise) return nihongoAiLoadPromise;
nihongoAiLoadPromise = new Promise((resolve) => {
const existing = document.querySelector('script[src$="nihongo-ai.js"]');
if (existing) { existing.addEventListener('load', () => resolve(window.NihongoAI || null)); return; }
const s = document.createElement('script');
s.src = `${rootPrefix}assets/nihongo-ai.js`;
s.onload = () => resolve(window.NihongoAI || null);
s.onerror = () => resolve(null);
document.head.appendChild(s);
});
return nihongoAiLoadPromise;
}
async function callApi(text, direction){
if (apiConfig.endpoint) {
try {
const response = await fetch(apiConfig.endpoint, {
method:'POST',
headers:{'Content-Type':'application/json'},
body:JSON.stringify({text,direction,model:apiConfig.model || 'translator'})
});
if (!response.ok) throw new Error('API error');
const data = await response.json();
const out = data.translation || data.output || data.text || null;
if (out) return out;
} catch (_) { }
}
const ai = await ensureNihongoAi();
if (!ai) return null;
try {
const hint = direction === 'ja-id' ? 'Terjemahkan ke bahasa Indonesia: '
: direction === 'id-ja' ? 'Terjemahkan ke bahasa Jepang: ' : '';
const data = await ai.translate(hint + text);
return data && data.text ? data.text : null;
} catch (_) {
return null;
}
}
function ensureUi(){
if (document.querySelector('.translator-launch')) return;
const launcher = document.createElement('button');
launcher.className = 'translator-launch';
launcher.type = 'button';
launcher.innerHTML = '<span>訳</span> Terjemahkan';
document.body.appendChild(launcher);
const panel = document.createElement('section');
panel.className = 'translator-panel';
panel.innerHTML = `
<div class="translator-head">
<div class="translator-title"><strong>訳</strong><span>Translator Pro <em class="translator-badge">AI + Kamus Lokal</em></span></div>
<button class="translator-close" type="button" aria-label="Tutup">&times;</button>
</div>
<div class="translator-body">
<div class="translator-toolbar">
<select class="translator-select" id="translatorDirection">
<option value="auto">Deteksi Otomatis</option>
<option value="ja-id">Jepang → Indonesia</option>
<option value="id-ja">Indonesia → Jepang</option>
</select>
<button class="translator-chip" type="button" id="translatorApiToggle">Endpoint lanjutan</button>
<button class="translator-chip" type="button" id="translatorClear">Clear</button>
</div>
<div class="translator-api" id="translatorApiBox">
<div class="translator-muted" style="margin-bottom:6px">AI Tanaka Sensei sudah aktif otomatis. Isi di bawah HANYA jika ingin memakai endpoint terjemahan kustom sendiri.</div>
<input class="translator-api-input" id="translatorEndpoint" placeholder="Endpoint kustom (opsional), contoh: /api/translate">
<input class="translator-api-input" id="translatorModel" placeholder="Nama model (opsional)">
</div>
<textarea class="translator-input" id="translatorInput" placeholder="Tulis bahasa Jepang, Indonesia, atau English. Contoh: 食べる, 日本語を勉強します, makan, belajar..."></textarea>
<div class="translator-actions">
<button class="primary" type="button" id="translatorRun">Terjemahkan</button>
<button type="button" id="translatorPasteCard">Ambil Kartu Ini</button>
<button type="button" id="translatorCopy">Copy Hasil</button>
<button type="button" id="translatorSwap">Swap Search</button>
</div>
<div class="translator-grid">
<div class="translator-box"><div class="translator-muted">Hasil</div><div class="translator-output" id="translatorOutput">Masukkan teks lalu klik Terjemahkan.</div></div>
<div class="translator-box"><div class="translator-muted">Analisis</div><div class="translator-output" id="translatorMeta">Kamus lokal siap dimuat.</div></div>
</div>
<div class="translator-section"><h4>Breakdown Kata</h4><div class="translator-token-list" id="translatorTokens"></div></div>
<div class="translator-section"><h4>Contoh Cepat</h4><div class="translator-tabs" id="translatorSamples">
<button class="translator-chip" type="button">食べる</button>
<button class="translator-chip" type="button">日本語を勉強します</button>
<button class="translator-chip" type="button">belajar</button>
<button class="translator-chip" type="button">reservation</button>
<button class="translator-chip" type="button">責任</button>
</div></div>
<div class="translator-section"><h4>Riwayat</h4><div class="translator-history" id="translatorHistory"></div></div>
</div>`;
document.body.appendChild(panel);
launcher.addEventListener('click', () => panel.classList.toggle('open'));
panel.querySelector('.translator-close').addEventListener('click', () => panel.classList.remove('open'));
panel.querySelector('#translatorApiToggle').addEventListener('click', () => panel.querySelector('#translatorApiBox').classList.toggle('open'));
panel.querySelector('#translatorClear').addEventListener('click', () => {
panel.querySelector('#translatorInput').value = '';
renderResult({output:'Masukkan teks lalu klik Terjemahkan.', tokens:[], source:'Ready'});
});
panel.querySelector('#translatorRun').addEventListener('click', runTranslate);
panel.querySelector('#translatorInput').addEventListener('keydown', event => {
if ((event.ctrlKey || event.metaKey) && event.key === 'Enter') runTranslate();
});
panel.querySelector('#translatorCopy').addEventListener('click', async () => {
const text = panel.querySelector('#translatorOutput').textContent;
try { await navigator.clipboard.writeText(text); window.proToast?.('Hasil terjemahan disalin.'); } catch (_) {}
});
panel.querySelector('#translatorPasteCard').addEventListener('click', () => {
const candidates = ['#frontWord','#backWord','#frontKanji','#backKanji','#prompt','.front-word','.back-word','.kanji','.char'];
const found = candidates.map(sel => document.querySelector(sel)?.textContent?.trim()).find(Boolean);
if (found) panel.querySelector('#translatorInput').value = found;
panel.classList.add('open');
});
panel.querySelector('#translatorSwap').addEventListener('click', () => {
const input = panel.querySelector('#translatorInput');
input.value = panel.querySelector('#translatorOutput').textContent.split('\n')[0] || input.value;
panel.querySelector('#translatorDirection').value = 'id-ja';
});
panel.querySelector('#translatorEndpoint').value = apiConfig.endpoint || '';
panel.querySelector('#translatorModel').value = apiConfig.model || '';
['translatorEndpoint','translatorModel'].forEach(id => {
panel.querySelector(`#${id}`).addEventListener('input', () => {
apiConfig = {endpoint:panel.querySelector('#translatorEndpoint').value.trim(), model:panel.querySelector('#translatorModel').value.trim()};
localStorage.setItem('nihongoTranslatorApi', JSON.stringify(apiConfig));
});
});
panel.querySelector('#translatorSamples').addEventListener('click', event => {
if (!event.target.matches('button')) return;
panel.querySelector('#translatorInput').value = event.target.textContent.trim();
runTranslate();
});
renderHistory();
}
function renderResult(result){
document.getElementById('translatorOutput').textContent = result.output;
document.getElementById('translatorMeta').textContent = `${result.source}\nItem: ${result.tokens?.length || 0}\nDictionary: ${entries.length.toLocaleString('id-ID')} entries`;
document.getElementById('translatorTokens').innerHTML = (result.tokens || []).slice(0, 30).map(t => `<div class="translator-token"><b>${esc(t.expression)}</b><span>${esc(t.reading || '-')}</span><span>${esc(t.meaning)}</span><span>${esc(t.level || '')}</span></div>`).join('') || '<div class="translator-muted">Belum ada breakdown.</div>';
}
function renderHistory(){
const box = document.getElementById('translatorHistory');
if (!box) return;
box.innerHTML = history.slice(0, 8).map(item => `<button type="button" data-text="${esc(item.text)}"><b>${esc(item.text)}</b><br>${esc(item.output.slice(0, 120))}</button>`).join('') || '<div class="translator-muted">Belum ada riwayat.</div>';
box.querySelectorAll('button').forEach(button => button.addEventListener('click', () => {
document.getElementById('translatorInput').value = button.dataset.text || '';
runTranslate();
}));
}
async function runTranslate(){
await loadVocab();
const input = document.getElementById('translatorInput');
const text = input.value.trim();
if (!text) return;
const direction = document.getElementById('translatorDirection').value;
renderResult({output:'Menerjemahkan...', tokens:[], source:'Loading'});
const api = await callApi(text, direction);
let result;
if (api) {
const localTokens = hasJapanese(text) ? tokenizeJapanese(text).filter(t => t.level !== 'Punctuation') : [];
result = {output:api, tokens:localTokens, source:'AI translation (Tanaka Sensei)'};
}
else if (direction === 'ja-id' || (direction === 'auto' && hasJapanese(text))) result = translateJapanese(text);
else result = translateSearch(text);
renderResult(result);
history = [{text, output:result.output, time:Date.now()}, ...history.filter(item => item.text !== text)].slice(0, 20);
localStorage.setItem('nihongoTranslatorHistory', JSON.stringify(history));
renderHistory();
}
window.openTranslatorPro = function(text){
ensureUi();
document.querySelector('.translator-panel').classList.add('open');
loadVocab().then(() => {
const meta = document.getElementById('translatorMeta');
if (meta) meta.textContent = `Kamus lokal siap.\nDictionary: ${entries.length.toLocaleString('id-ID')} entries\nMode: AI Tanaka Sensei (fallback kamus lokal)`;
});
if (text) document.getElementById('translatorInput').value = text;
if (text) runTranslate();
};
document.addEventListener('DOMContentLoaded', () => {
ensureUi();
});
})();